import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def pref_prob(r_a, r_b):
    return sigmoid(r_a - r_b)

def rm_loss(r_chosen, r_rejected):
    return -math.log(pref_prob(r_chosen, r_rejected))

